const source = $('Webhook Create').item.json || {};
const query = source.query || {};
const rawUrl = String(query.url || source.body?.url || '').trim();
const rawTtl = String(query.ttl || source.body?.ttl || '').trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function escapeSql(value = '') {
  return String(value || '').replace(/'/g, "''");
}

function parseDuration(value) {
  const text = normalize(value);
  if (!text) return null;
  if (/\b(vinh vien|khong het han|forever)\b/.test(text)) {
    return { forever: true, ms: null, label: 'Vinh vien' };
  }
  const compact = text.match(/(\d+)\s*(h|d|w)\b/);
  if (compact) {
    const amount = Number(compact[1]);
    const unit = compact[2];
    if (unit === 'h') return { forever: false, ms: amount * 3600 * 1000, label: `${amount}h` };
    if (unit === 'd') return { forever: false, ms: amount * 24 * 3600 * 1000, label: `${amount}d` };
    if (unit === 'w') return { forever: false, ms: amount * 7 * 24 * 3600 * 1000, label: `${amount}w` };
  }
  const verbose = text.match(/(\d+)\s*(gio|ngay|tuan|thang|hour|day|week|month)\b/);
  if (verbose) {
    const amount = Number(verbose[1]);
    const unit = verbose[2];
    if (unit === 'gio' || unit === 'hour') return { forever: false, ms: amount * 3600 * 1000, label: `${amount} gio` };
    if (unit === 'ngay' || unit === 'day') return { forever: false, ms: amount * 24 * 3600 * 1000, label: `${amount} ngay` };
    if (unit === 'tuan' || unit === 'week') return { forever: false, ms: amount * 7 * 24 * 3600 * 1000, label: `${amount} tuan` };
    if (unit === 'thang' || unit === 'month') return { forever: false, ms: amount * 30 * 24 * 3600 * 1000, label: `${amount} thang` };
  }
  return null;
}

function isPrivateHost(hostname) {
  const host = String(hostname || '').toLowerCase();
  if (!host) return true;
  if (host === 'localhost' || host === '0.0.0.0' || host === '127.0.0.1' || host === '::1') return true;
  if (host.endsWith('.local')) return true;
  if (/^10\./.test(host)) return true;
  if (/^192\.168\./.test(host)) return true;
  if (/^172\.(1[6-9]|2\d|3[0-1])\./.test(host)) return true;
  return false;
}

if (!rawUrl) {
  return [{ json: { ok: false, error: 'Missing url parameter', example: '/webhook/shortlink/create?url=https%3A%2F%2Fexample.com&ttl=7d', responseCode: 400 } }];
}

let parsedUrl;
try {
  parsedUrl = new URL(rawUrl);
} catch (error) {
  return [{ json: { ok: false, error: 'Invalid URL', responseCode: 400 } }];
}

const protocol = String(parsedUrl.protocol || '').toLowerCase();
if (protocol !== 'http:' && protocol !== 'https:') {
  return [{ json: { ok: false, error: 'Only http:// and https:// are allowed', responseCode: 400 } }];
}

const allowLocal = String($env.SHORTLINK_ALLOW_LOCAL || 'false').toLowerCase() === 'true';
if (!allowLocal && isPrivateHost(parsedUrl.hostname)) {
  return [{ json: { ok: false, error: 'Local/internal hosts are blocked by default', responseCode: 400 } }];
}

const publicBaseUrl = String($env.SHORTLINK_PUBLIC_BASE_URL || 'https://go.huynhminh.com').replace(/\/+$/, '');
const defaultTtl = parseDuration($env.SHORTLINK_DEFAULT_TTL || '30d') || { forever: false, ms: 30 * 24 * 3600 * 1000, label: '30d' };
const requestedTtl = parseDuration(rawTtl);
const maxDays = Number($env.SHORTLINK_MAX_TTL_DAYS || 365) || 365;
const maxMs = maxDays * 24 * 3600 * 1000;
let ttl = requestedTtl || defaultTtl;
let clamped = false;
if (!ttl.forever && ttl.ms > maxMs) {
  ttl = { forever: false, ms: maxMs, label: `${maxDays} ngay` };
  clamped = true;
}

const expiresAt = ttl.forever ? null : new Date(Date.now() + ttl.ms);
const expiresAtIso = expiresAt ? expiresAt.toISOString() : null;
const crypto = require('crypto');
const hash = crypto.createHash('sha256').update(`${rawUrl}|${publicBaseUrl}`).digest('hex');
const candidateId8 = hash.slice(0, 8);
const candidateId10 = hash.slice(0, 10);
const candidateId12 = hash.slice(0, 12);
const lookupSql = `SELECT id, long_url, short_url, host, clicks, created_at, expires_at, updated_at, last_clicked_at FROM short_links WHERE long_url = '${escapeSql(rawUrl)}' OR id IN ('${candidateId8}', '${candidateId10}', '${candidateId12}') ORDER BY created_at DESC;`;

return [{ json: {
  ok: true,
  longUrl: rawUrl,
  host: parsedUrl.host,
  publicBaseUrl,
  expiresAtIso,
  expiresAtSql: expiresAtIso ? `'${expiresAtIso}'::timestamptz` : 'NULL',
  requestedTtlLabel: requestedTtl ? requestedTtl.label : defaultTtl.label,
  effectiveTtlLabel: ttl.forever ? 'Vinh vien' : ttl.label,
  clamped,
  responseCode: 200,
  candidateId8,
  candidateId10,
  candidateId12,
  lookupSql
} }];

const source = $('Prepare Create Request').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((row) => row.id || row.long_url);

function escapeSql(value = '') {
  return String(value || '').replace(/'/g, "''");
}

function isExpired(row) {
  return Boolean(row.expires_at && new Date(row.expires_at).getTime() <= Date.now());
}

const sameUrl = rows.find((row) => row.long_url === source.longUrl);
const byId = new Map(rows.filter((row) => row.id).map((row) => [row.id, row]));
const candidates = [source.candidateId8, source.candidateId10, source.candidateId12];
let persistSql = '';

if (sameUrl) {
  if (isExpired(sameUrl)) {
    persistSql = `UPDATE short_links SET expires_at = ${source.expiresAtSql}, updated_at = now() WHERE id = '${escapeSql(sameUrl.id)}' RETURNING id, long_url, short_url, host, clicks, created_at, expires_at, updated_at, last_clicked_at;`;
  } else {
    persistSql = `SELECT id, long_url, short_url, host, clicks, created_at, expires_at, updated_at, last_clicked_at FROM short_links WHERE id = '${escapeSql(sameUrl.id)}' LIMIT 1;`;
  }
} else {
  const freeCandidate = candidates.find((id) => !byId.has(id));
  if (!freeCandidate) {
    return [{ json: { ok: false, error: 'ID collision across 8/10/12 chars', responseCode: 409 } }];
  }
  const shortUrl = `${source.publicBaseUrl}/${freeCandidate}`;
  persistSql = `INSERT INTO short_links (id, long_url, short_url, host, expires_at, created_at, updated_at) VALUES ('${freeCandidate}', '${escapeSql(source.longUrl)}', '${escapeSql(shortUrl)}', '${escapeSql(source.host)}', ${source.expiresAtSql}, now(), now()) RETURNING id, long_url, short_url, host, clicks, created_at, expires_at, updated_at, last_clicked_at;`;
}

return [{ json: { ...source, ok: true, persistSql, responseCode: 200 } }];

const source = $('Prepare Create Request').item.json || {};
const row = $input.item.json || {};
const expiresAt = row.expires_at || source.expiresAtIso || null;
return [{ json: {
  ok: true,
  id: row.id,
  shortUrl: row.short_url,
  longUrl: row.long_url,
  host: row.host,
  clicks: row.clicks,
  expiresAt,
  requestedTtl: source.requestedTtlLabel,
  effectiveTtl: source.effectiveTtlLabel,
  clamped: Boolean(source.clamped)
} }];
